import type { Metadata } from 'next';
import Link from 'next/link';
import { headers } from 'next/headers';
import { notFound, redirect } from 'next/navigation';
import QRCode from 'qrcode';
import type { ItemCondition, RequestStatus } from '@prisma/client';
import { getSession } from '@/lib/auth';
import { getLoanForm, runMaintenance } from '@/lib/borrow-workflow';
import { ROLE_LABELS } from '@/components/StatusBadge';
import PrintButton from './PrintButton';

// Printable Equipment Loan Form (A4). The browser's "Save as PDF" turns it into the PDF,
// so nothing is generated by an external service and no PDF library is needed.
// Read-only view of the live record: it is available once a Coordinator has recommended
// the request and stays available afterwards. Handover / return codes are never shown.

type Props = { params: Promise<{ id: string }> };

const NAVY = '#1e3a5f';
const GOLD = '#b08d3c';

function refFor(id: string) {
  return `RUH-IMS-${id.slice(0, 8).toUpperCase()}`;
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params;
  // Browsers use the page title as the default PDF file name.
  return { title: `Equipment Loan Form ${refFor(id)}` };
}

const dateFmt = new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
const timeFmt = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', hour12: true });
const fDate = (d?: Date | null) => (d ? dateFmt.format(d) : null);
const fDateTime = (d?: Date | null) => (d ? `${dateFmt.format(d)}, ${timeFmt.format(d)}` : null);

const DAY_MS = 24 * 60 * 60 * 1000;

const STATUS: Partial<Record<RequestStatus, { label: string; className: string; watermark?: string }>> = {
  APPROVED: { label: 'Recommended · Reserved', className: 'bg-blue-50 text-blue-800 border-blue-300' },
  ISSUED: { label: 'Issued · On Loan', className: 'bg-indigo-50 text-indigo-800 border-indigo-300' },
  OVERDUE: { label: 'Overdue · On Loan', className: 'bg-rose-50 text-rose-800 border-rose-300' },
  RETURNED: { label: 'Returned · Closed', className: 'bg-emerald-50 text-emerald-800 border-emerald-300', watermark: 'RETURNED' },
  CANCELLED: { label: 'Cancelled · Void', className: 'bg-slate-100 text-slate-700 border-slate-400', watermark: 'VOID' },
  EXPIRED: { label: 'Expired · Void', className: 'bg-slate-100 text-slate-700 border-slate-400', watermark: 'VOID' },
};

const CONDITION_LABELS: Record<ItemCondition, string> = {
  WORKING: 'Working — fit for use',
  DAMAGED: 'Damaged',
  UNDER_REPAIR: 'Under repair',
};

const PRINT_CSS = `
@page { size: A4; margin: 11mm; }
@media print {
  html, body { background: #ffffff !important; }
  * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
}
`;

// ---------------------------------------------------------------------------
// building blocks
// ---------------------------------------------------------------------------

function Section({ n, title, children, className = '' }: { n: number; title: string; children: React.ReactNode; className?: string }) {
  return (
    <section className={`break-inside-avoid ${className}`}>
      <h2
        className="flex items-center gap-2 border-b border-slate-200 pb-1 mb-2 text-[9px] font-bold uppercase tracking-[0.18em]"
        style={{ color: NAVY }}
      >
        <span
          className="inline-flex h-4 w-4 items-center justify-center rounded-full text-[8px] tracking-normal text-white"
          style={{ backgroundColor: NAVY }}
        >
          {n}
        </span>
        {title}
      </h2>
      <dl className="grid grid-cols-2 gap-x-4 gap-y-1.5">{children}</dl>
    </section>
  );
}

// `writeIn` leaves a dotted line to complete by hand when the stage has not happened yet.
function Field({
  label,
  value,
  wide,
  mono,
  writeIn,
}: {
  label: string;
  value?: React.ReactNode;
  wide?: boolean;
  mono?: boolean;
  writeIn?: boolean;
}) {
  const empty = value === null || value === undefined || value === '';
  return (
    <div className={wide ? 'col-span-2' : ''}>
      <dt className="text-[7.5px] font-semibold uppercase tracking-wider text-slate-500">{label}</dt>
      <dd className={`text-[10.5px] leading-snug text-slate-900 ${mono ? 'font-mono' : ''}`}>
        {empty ? (
          writeIn ? (
            <span className="block h-[15px] border-b border-dotted border-slate-400" />
          ) : (
            <span className="text-slate-400">—</span>
          )
        ) : (
          value
        )}
      </dd>
    </div>
  );
}

function Seal() {
  return (
    <svg viewBox="0 0 64 64" className="h-14 w-14 shrink-0" aria-hidden="true">
      <circle cx="32" cy="32" r="31" fill={NAVY} />
      <circle cx="32" cy="32" r="27" fill="none" stroke={GOLD} strokeWidth="1.2" />
      <circle cx="32" cy="32" r="24.5" fill="none" stroke={GOLD} strokeWidth="0.5" />
      <text x="32" y="30" textAnchor="middle" fill="#ffffff" fontFamily="Georgia, serif" fontSize="12" fontWeight="700" letterSpacing="1">
        DEIE
      </text>
      <text x="32" y="41" textAnchor="middle" fill={GOLD} fontFamily="Georgia, serif" fontSize="5.2" letterSpacing="1.2">
        RUHUNA
      </text>
    </svg>
  );
}

type StepState = 'done' | 'next' | 'todo' | 'void';
interface Step {
  label: string;
  at: Date | null;
  by?: string | null;
  state: StepState;
}

function Timeline({ steps }: { steps: Step[] }) {
  const dot: Record<StepState, string> = {
    done: 'border-transparent',
    next: 'bg-white border-slate-400 border-dashed',
    todo: 'bg-white border-slate-300',
    void: 'bg-slate-500 border-slate-500',
  };
  return (
    <ol className="grid" style={{ gridTemplateColumns: `repeat(${steps.length}, minmax(0, 1fr))` }}>
      {steps.map((s, i) => (
        <li key={s.label} className="relative flex flex-col items-center px-1 text-center">
          {i > 0 && (
            <span
              className="absolute top-[7px] right-1/2 h-[2px] w-full"
              style={{ backgroundColor: s.state === 'done' || s.state === 'void' ? NAVY : '#e2e8f0' }}
            />
          )}
          <span
            className={`relative z-10 h-4 w-4 rounded-full border-2 ${dot[s.state]}`}
            style={s.state === 'done' ? { backgroundColor: NAVY, boxShadow: `0 0 0 2px #fff, 0 0 0 3px ${GOLD}` } : undefined}
          />
          <span className="mt-1.5 text-[8.5px] font-bold uppercase tracking-wider text-slate-800">{s.label}</span>
          <span className="text-[9px] text-slate-600">{fDateTime(s.at) ?? (s.state === 'next' ? 'Awaiting' : '—')}</span>
          {s.by && <span className="text-[9px] text-slate-500">{s.by}</span>}
        </li>
      ))}
    </ol>
  );
}

function SignatureCell({ title, caption }: { title: string; caption: string }) {
  return (
    <div className="rounded-md border border-slate-200 px-2.5 pt-2 pb-1.5">
      <p className="text-[8px] font-bold uppercase tracking-wider text-slate-700">{title}</p>
      <p className="text-[7.5px] text-slate-500">{caption}</p>
      <div className="mt-5 border-b border-slate-400" />
      <div className="mt-0.5 flex justify-between text-[7px] uppercase tracking-wider text-slate-400">
        <span>Signature &amp; name</span>
        <span>Date</span>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// page
// ---------------------------------------------------------------------------

export default async function LoanFormPage({ params }: Props) {
  const { id } = await params;
  const session = await getSession();
  if (!session) redirect('/api/auth/logout');

  // Same lazy maintenance as the request list, so an uncollected reservation is shown
  // as expired rather than as still reserved.
  await runMaintenance();
  const log = await getLoanForm(session, id);
  if (!log) notFound();

  const ref = refFor(log.id);
  const status = STATUS[log.status] ?? { label: log.status, className: 'bg-slate-100 text-slate-700 border-slate-300' };
  const isVoid = log.status === 'CANCELLED' || log.status === 'EXPIRED';
  const now = new Date();

  // QR code that opens this live record (university network + sign-in required).
  const h = await headers();
  const host = h.get('x-forwarded-host') ?? h.get('host');
  const proto = (h.get('x-forwarded-proto') ?? 'http').split(',')[0].trim();
  const verifyUrl = host ? `${proto}://${host}/dashboard/borrow/${log.id}/form` : null;
  const qrSvg = verifyUrl
    ? await QRCode.toString(verifyUrl, { type: 'svg', margin: 0, errorCorrectionLevel: 'M', color: { dark: '#0f172a', light: '#ffffff' } })
    : null;

  const loanDays = Math.max(1, Math.round((log.returnDate.getTime() - log.borrowDate.getTime()) / DAY_MS));
  let returnTiming: string | null = null;
  if (log.actualReturn) {
    const late = Math.ceil((log.actualReturn.getTime() - log.returnDate.getTime()) / DAY_MS);
    returnTiming = late > 0 ? `Returned ${late} day(s) after the due date` : 'Returned on time';
  } else if (log.status === 'OVERDUE') {
    const late = Math.ceil((now.getTime() - log.returnDate.getTime()) / DAY_MS);
    returnTiming = `Overdue by ${late} day(s) at time of printing`;
  }

  const steps: Step[] = [
    { label: 'Submitted', at: log.createdAt, by: log.user.name, state: 'done' },
    { label: 'Recommended', at: log.approvedAt, by: log.approvedBy?.name, state: 'done' },
  ];
  if (log.status === 'CANCELLED') {
    steps.push({ label: 'Cancelled', at: log.cancelledAt, by: log.cancelledBy?.name, state: 'void' });
  } else if (log.status === 'EXPIRED') {
    steps.push({ label: 'Expired', at: log.expiredAt, by: 'Not collected', state: 'void' });
  } else {
    steps.push({ label: 'Issued', at: log.issuedAt, by: log.issuedBy?.name, state: log.issuedAt ? 'done' : 'next' });
    steps.push({
      label: 'Returned',
      at: log.actualReturn,
      by: log.returnedBy?.name,
      state: log.actualReturn ? 'done' : log.issuedAt ? 'next' : 'todo',
    });
  }

  const brandModel = [log.equipment.brand, log.equipment.model].filter(Boolean).join(' · ');
  const writeIn = !isVoid; // blank lines for stages still to come (manual backup)

  return (
    <div className="min-h-full bg-slate-200/70 py-8 print:bg-white print:py-0">
      <style>{PRINT_CSS}</style>

      {/* Toolbar (screen only) */}
      <div className="mx-auto mb-4 flex max-w-[210mm] flex-wrap items-center justify-between gap-3 px-4 print:hidden">
        <Link href="/dashboard/borrow" className="text-sm font-medium text-slate-600 hover:text-blue-600">
          ← Back to requests
        </Link>
        <div className="flex items-center gap-3">
          <span className="hidden text-xs text-slate-500 sm:inline">Tip: choose “Save as PDF” as the destination to download.</span>
          <PrintButton />
        </div>
      </div>

      <div className="overflow-x-auto px-4 print:overflow-visible print:px-0">
        <article className="relative mx-auto min-h-[297mm] w-[210mm] overflow-hidden bg-white p-[12mm] font-sans text-slate-900 shadow-xl print:min-h-0 print:w-auto print:p-0 print:shadow-none">
          {/* Watermark for closed / void records, so an old printout is not mistaken for a live reservation */}
          {status.watermark && (
            <div className="pointer-events-none absolute inset-0 flex items-center justify-center" aria-hidden="true">
              <span className="-rotate-[30deg] select-none font-serif text-[120px] font-bold tracking-[0.15em] text-slate-900/[0.05]">
                {status.watermark}
              </span>
            </div>
          )}

          {/* Letterhead */}
          <header className="relative flex items-start justify-between gap-6">
            <div className="flex items-center gap-3">
              <Seal />
              <div>
                <p className="text-[9px] font-bold uppercase tracking-[0.3em]" style={{ color: GOLD }}>
                  University of Ruhuna
                </p>
                <p className="font-serif text-[15px] font-bold leading-tight" style={{ color: NAVY }}>
                  Faculty of Engineering
                </p>
                <p className="font-serif text-[11px] leading-tight text-slate-700">
                  Department of Electrical and Information Engineering
                </p>
              </div>
            </div>
            <div className="text-right">
              <p className="font-serif text-[19px] font-bold leading-none" style={{ color: NAVY }}>
                Equipment Loan Form
              </p>
              <p className="mt-1 text-[9px] uppercase tracking-[0.2em] text-slate-500">Ruhuna IMS · Official Record</p>
              <p className="mt-1.5 font-mono text-[11px] font-semibold text-slate-800">Ref. {ref}</p>
              <span className={`mt-1.5 inline-block rounded-full border px-2.5 py-0.5 text-[8.5px] font-bold uppercase tracking-wider ${status.className}`}>
                {status.label}
              </span>
            </div>
          </header>

          <div className="mt-3 h-[3px]" style={{ backgroundColor: NAVY }} />
          <div className="mt-[2px] h-px" style={{ backgroundColor: GOLD }} />

          {/* Summary band */}
          <div className="mt-4 grid grid-cols-4 divide-x divide-slate-200 rounded-lg border border-slate-200 bg-slate-50">
            {[
              { k: 'Equipment', v: log.equipment.name },
              { k: 'Serial / Asset No.', v: log.unit?.serialNumber ?? '—', mono: true },
              { k: 'Laboratory', v: log.equipment.lab.name },
              { k: 'Loan Period', v: `${fDate(log.borrowDate)} → ${fDate(log.returnDate)}` },
            ].map((c) => (
              <div key={c.k} className="px-3 py-2">
                <p className="text-[7.5px] font-semibold uppercase tracking-wider text-slate-500">{c.k}</p>
                <p className={`text-[11px] font-semibold leading-snug text-slate-900 ${c.mono ? 'font-mono' : ''}`}>{c.v}</p>
              </div>
            ))}
          </div>

          {/* Progress */}
          <div className="mt-4 break-inside-avoid">
            <Timeline steps={steps} />
          </div>

          {/* Details */}
          <div className="mt-4 grid grid-cols-2 gap-x-6 gap-y-4">
            <Section n={1} title="Borrower">
              <Field label="Name" value={log.user.name} />
              <Field label="University e-mail" value={log.user.email} mono />
              <Field label="Request submitted" value={fDateTime(log.createdAt)} />
              <Field label="Loan duration" value={`${loanDays} day(s)`} />
              <Field label="Purpose / notes" value={log.notes} wide />
            </Section>

            <Section n={2} title="Equipment">
              <Field label="Equipment type" value={log.equipment.name} />
              <Field label="Brand · Model" value={brandModel || null} />
              <Field
                label="Serial / asset no."
                mono
                value={
                  log.unit ? (
                    <>
                      {log.unit.serialNumber}
                      {log.unit.serialIsPlaceholder && (
                        <span className="ml-1 font-sans text-[8.5px] text-slate-500">(system asset tag)</span>
                      )}
                    </>
                  ) : null
                }
              />
              <Field label="Storage location" value={log.unit?.location} />
              <Field label="Laboratory" value={log.equipment.lab.name} wide />
            </Section>

            <Section n={3} title="Coordinator Recommendation">
              <Field label="Recommended by" value={log.approvedBy?.name} />
              <Field label="Date & time" value={fDateTime(log.approvedAt)} />
              <Field label="Coordinator e-mail" value={log.approvedBy?.email} mono />
              <Field label="Collect before" value={fDateTime(log.reservationExpiresAt)} />
              {log.approvedById === log.userId && (
                <Field
                  wide
                  label="Note"
                  value={
                    <span className="text-amber-800">
                      Recommended by the requester (own request). Recorded as self-recommended; not an independent approval.
                    </span>
                  }
                />
              )}
            </Section>

            {isVoid ? (
              <Section n={4} title={log.status === 'CANCELLED' ? 'Cancellation' : 'Reservation Expiry'}>
                {log.status === 'CANCELLED' ? (
                  <>
                    <Field label="Cancelled by" value={log.cancelledBy?.name} />
                    <Field label="Date & time" value={fDateTime(log.cancelledAt)} />
                    <Field label="Reason" value={log.cancelReason} wide />
                  </>
                ) : (
                  <>
                    <Field label="Expired on" value={fDateTime(log.expiredAt)} />
                    <Field label="Reason" value="Not collected before the deadline" />
                  </>
                )}
                <Field
                  wide
                  label="Validity"
                  value={<span className="font-semibold">This form is void. The reserved unit was released and must not be issued against it.</span>}
                />
              </Section>
            ) : (
              <Section n={4} title="Issue · Physical Handover">
                <Field label="Issued by (Technical Officer)" value={log.issuedBy?.name} writeIn={writeIn} />
                <Field label="Date & time" value={fDateTime(log.issuedAt)} writeIn={writeIn} />
                <Field label="Condition / accessories at issue" value={log.issueNotes ?? (log.issuedAt ? 'No notes recorded' : null)} wide writeIn={writeIn} />
                <Field label="Due for return" value={fDate(log.returnDate)} />
                <Field label="Handover confirmation" value={log.issuedAt ? 'Verified with one-time code' : null} writeIn={writeIn} />
              </Section>
            )}
          </div>

          {!isVoid && (
            <div className="mt-4">
              <Section n={5} title="Return · Inspection & Completion">
                <div className="col-span-2 grid grid-cols-4 gap-x-4 gap-y-1.5">
                  <Field label="Inspected by" value={log.returnInitiatedBy?.name} writeIn={writeIn} />
                  <Field label="Inspected on" value={fDateTime(log.returnInitiatedAt)} writeIn={writeIn} />
                  <Field label="Condition on return" value={log.returnCondition ? CONDITION_LABELS[log.returnCondition] : null} writeIn={writeIn} />
                  <Field
                    label="Borrower acknowledgement"
                    writeIn={writeIn}
                    value={
                      log.returnAcknowledgedAt
                        ? `Code entered ${fDateTime(log.returnAcknowledgedAt)}`
                        : log.returnAckOverrideBy
                          ? `Recorded by ${log.returnAckOverrideBy.name} (Coordinator)`
                          : null
                    }
                  />
                  <Field label="Return completed by" value={log.returnedBy?.name} writeIn={writeIn} />
                  <Field label="Completed on" value={fDateTime(log.actualReturn)} writeIn={writeIn} />
                  <Field
                    label="Return timing"
                    value={
                      returnTiming && (
                        <span className={log.status === 'OVERDUE' || returnTiming.includes('after') ? 'text-rose-700 font-semibold' : 'text-emerald-700 font-semibold'}>
                          {returnTiming}
                        </span>
                      )
                    }
                  />
                  <Field label="Current status" value={status.label} />
                  <Field label="Inspection notes" value={log.returnNotes} wide writeIn={writeIn && !log.returnInitiatedAt} />
                  {log.returnAckOverrideReason && (
                    <Field label="Acknowledgement override reason" value={log.returnAckOverrideReason} wide />
                  )}
                </div>
              </Section>
            </div>
          )}

          {/* Manual signatures (backup when the digital confirmation cannot be recorded) */}
          {!isVoid && (
            <div className="mt-4 break-inside-avoid">
              <p className="mb-1.5 text-[8px] font-bold uppercase tracking-[0.18em] text-slate-500">
                Signatures <span className="font-normal normal-case tracking-normal">— complete by hand only if the digital confirmation cannot be recorded</span>
              </p>
              <div className="grid grid-cols-3 gap-3">
                <SignatureCell title="Borrower" caption="Received the item in the condition stated" />
                <SignatureCell title="Technical Officer — Issue" caption="Handed over the unit identified above" />
                <SignatureCell title="Technical Officer — Return" caption="Received and inspected the returned unit" />
              </div>
            </div>
          )}

          {/* Exceptions & remarks */}
          <div className="mt-4 break-inside-avoid rounded-lg border-2 border-dashed border-slate-300 px-3 pt-2 pb-2.5">
            <div className="flex items-baseline justify-between gap-4">
              <p className="text-[8.5px] font-bold uppercase tracking-[0.18em]" style={{ color: NAVY }}>
                Exceptions &amp; Remarks
              </p>
              <p className="text-[7.5px] text-slate-500">
                For the Laboratory Coordinator, Technical Officer or Super Admin — events outside the normal workflow
              </p>
            </div>
            <div className="mt-1">
              {[0, 1, 2].map((i) => (
                <div key={i} className="h-[18px] border-b border-slate-300" />
              ))}
            </div>
            <div className="mt-2 grid grid-cols-4 gap-3 text-[7px] uppercase tracking-wider text-slate-400">
              {['Name', 'Role', 'Signature', 'Date'].map((k) => (
                <div key={k}>
                  <div className="h-[14px] border-b border-slate-400" />
                  <span>{k}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Footer */}
          <footer className="mt-4 flex items-end gap-4 border-t border-slate-200 pt-3 break-inside-avoid">
            {qrSvg && (
              <div className="shrink-0 text-center">
                <div className="h-[19mm] w-[19mm] [&>svg]:h-full [&>svg]:w-full" dangerouslySetInnerHTML={{ __html: qrSvg }} />
                <p className="mt-0.5 text-[6.5px] uppercase tracking-wider text-slate-400">Verify live</p>
              </div>
            )}
            <div className="flex-1 space-y-0.5 text-[8px] leading-snug text-slate-500">
              <p>
                <span className="font-semibold text-slate-700">The digital record in Ruhuna IMS is authoritative.</span> Scan the code on the
                university network (sign-in required) to confirm the current status. Manual entries on this form should be recorded in the
                system once it is available.
              </p>
              <p>Handover and return codes are never printed on this form. Do not write them on it.</p>
              <p className="font-mono text-[7px] text-slate-400">Record ID {log.id}</p>
            </div>
            <div className="shrink-0 text-right text-[8px] leading-snug text-slate-500">
              <p className="uppercase tracking-wider text-slate-400">Generated</p>
              <p className="font-semibold text-slate-700">{fDateTime(now)}</p>
              <p>
                by {session.name} ({ROLE_LABELS[session.role]})
              </p>
            </div>
          </footer>
        </article>
      </div>
    </div>
  );
}
